function run(text, o = {}) { return new TextRun({ text, font: 'Arial', size: o.size || 20, color: o.color || CHAR, bold: o.bold || false, italics: o.italics || false }); }
function para(text, o = {}) { return new Paragraph({ children: [run(text, o)], alignment: o.align || AlignmentType.LEFT, spacing: { before: o.before || 0, after: o.after ?? 125, line: o.line || 276 }, keepLines: o.keep || false }); }
function border(color = GOLD, size = 6) { return new Paragraph({ border: { bottom: { color, size, style: BorderStyle.SINGLE, space: 1 } }, spacing: { before: 50, after: 130 } }); }
function cell(text, fill, textColor = CHAR, bold = false) { return new TableCell({ shading: { type: ShadingType.CLEAR, fill }, margins: { top: 110, bottom: 110, left: 120, right: 120 }, children: [para(text, { size: 17, color: textColor, bold, after: 0, line: 240 })] }); }
function table(rows, widths) { return new Table({ width: { size: 9000, type: WidthType.DXA }, columnWidths: widths, rows: rows.map((r,i) => new TableRow({ children: r.map(x => cell(x, i === 0 ? NAVY : (i % 2 ? ICE : WHITE), i === 0 ? WHITE : CHAR, i === 0)) })) }); }
function logo(width) { return new ImageRun({ data: fs.readFileSync(LOGO), transformation: { width, height: Math.round(width * 0.558) }, type: 'png', altText: { title: 'MylesCorp Technologies Ltd logo', description: 'MylesCorp Technologies Ltd official logo', name: 'MylesCorpLogo' } }); }
function link(label, url) { return new ExternalHyperlink({ link: url, children: [new TextRun({ text: label, style: 'Hyperlink', color: NAVY, font: 'Arial', size: 16 })] }); }

function header() { return new Header({ children: [new Paragraph({ children: [logo(145)], spacing: { after: 30 } }), new Paragraph({ children: [run('MYLESNET MULTI TENANT ISP AND RADIUS SAAS | INTERNAL CONFIDENTIAL', { size: 13, color: NAVY, bold: true })], alignment: AlignmentType.RIGHT, spacing: { after: 35 } }), border()] }); }
function footer() { return new Footer({ children: [border(), new Paragraph({ children: [run('MylesCorp Technologies Ltd | +254743993715 | ', { size: 14, color: GREY }), link('info@mylescorptech.com', 'mailto:info@mylescorptech.com'), run(' | ', { size: 14, color: GREY }), link('https://mylescorptech.com/', 'https://mylescorptech.com/')], alignment: AlignmentType.CENTER, spacing: { after: 25 } }), new Paragraph({ children: [run('Transforming Industries, Empowering Generations. | Page ', { size: 13, color: GOLD, italics: true }), PageNumber.CURRENT, run(' of ', { size: 13, color: GREY }), PageNumber.TOTAL_PAGES], alignment: AlignmentType.CENTER })] }); }

function section(title, body, n) {
  const nodes = [new Paragraph({ text: `${n}. ${title}`, heading: HeadingLevel.HEADING_1, pageBreakBefore: true, spacing: { before: 80, after: 70 } }), border(NAVY, 5)];
  body.forEach(p => {
    if (n >= 20) {
      const splitAt = p.indexOf('. ');
      if (splitAt > 0) {
        nodes.push(new Paragraph({ text: p.slice(0, splitAt), heading: HeadingLevel.HEADING_2, spacing: { before: 135, after: 35 } }));
        nodes.push(para(p.slice(splitAt + 2)));
        return;
      }
    }
    nodes.push(para(p));
  });
  if (title === 'Current implementation evidence and gap assessment') nodes.push(table([['Area', 'Status', 'Evidence and required action'], ['Application foundation', 'Verified', 'Next.js, React, TypeScript, Convex and WorkOS packages are present; retain current controls while introducing tenant boundaries.'], ['Router and collector', 'Verified design / unverified live proof', 'Router, AP, switch and collector structures exist. Replace shared secret with mTLS and require a fresh LAN sample.'], ['Multi tenancy and RADIUS', 'Planned', 'TenantId, RLS, tenant onboarding, FreeRADIUS, subscriber lifecycle and HA are not established as universal production capabilities.'], ['Provider integration', 'Approval gated', 'Centipid, M-Pesa, SMS and email require authoritative contracts, credentials and end-to-end verification.']], [2100, 1500, 5400]));
  if (title === 'Panel and route architecture') nodes.push(table([['Panel', 'Host and route', 'Boundary'], ['Platform', 'admin.<product-domain> /platform', 'MylesCorp tenant lifecycle, SaaS billing, support, security and audit.'], ['Admin', 'network.<product-domain> /admin', 'MylesCorp shared RADIUS and infrastructure operations; never tenant NOC.'], ['Dashboard', '<tenant>.<product-domain> /dashboard', 'Tenant staff operations, network, AAA, subscribers, finance and settings.'], ['Subscriber portal', '<tenant>.<product-domain> /dashboard/portal', 'Subscriber self service only.'], ['Reseller', 'reseller.<product-domain> /reseller', 'Assigned sales, vouchers, commission and settlement.']], [1600, 3000, 4400]));
  if (title === 'WorkOS identity and authorization') nodes.push(table([['Scope', 'WorkOS role boundary', 'Convex responsibility'], ['MylesNet Platform', 'Platform owner, admin and support', 'Fine permissions, support grants, global controls and audit.'], ['MylesNet Network', 'Network owner, admin and operator', 'Node, NAS, connector, queue and RADIUS operation permissions.'], ['ISP tenant organization', 'Tenant admin, NOC, finance, sales, reseller and viewer', 'Site scope, market scope, module entitlements and operation authority.']], [2300, 3400, 3300]));
  return nodes;
}

function markdown() {
  const toc = content.map((x,i) => `${i+1}. [${x[0]}](#${x[0].toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')})`).join('\n');
  const renderedSections = content.map((x,i) => {
    const body = x[1].map(p => {
      if (i >= 19) {
        const splitAt = p.indexOf('. ');
        if (splitAt > 0) return `### ${p.slice(0, splitAt)}\n\n${p.slice(splitAt + 2)}`;
      }
      return p;
    }).join('\n\n');
    return `## ${i+1}. ${x[0]}\n\n${body}`;
  }).join('\n\n');
  return `---\ntype: technical-specification\nstatus: proposed-canonical-v3\ndate: 2026-09-08\nclassification: internal-confidential\nauthor: [[Jonathan Myles]]\nproduct: [[MylesNet]]\ncompany: [[MylesCorp Technologies Ltd]]\n---\n\n# ${TITLE}\n\nPrepared by [[Jonathan Myles]] for [[MylesCorp Technologies Ltd]]. Classification: Internal Confidential.\n\n## Table of contents\n\n${toc}\n\n${renderedSections}\n\n## Related\n\n- [[MylesNet]]\n- [[MylesNet Technical Specification v2]]\n- [[MylesNet Implementation Plan]]\n- [[Panel Naming Convention]]\n- [[Multi-Tenancy Enforcement Standards]]\n- [[WorkOS AuthKit]]\n`;
}

